      "applies_to_keys":["world_model_result_domains","identity_direction","markov_overlay","markov_object"],
      "conditions":["A verification has not run and neither extraction_inadmissible nor representation_space_invalid grounds hold."],
      "exceptions":["Publishing the unverified direction separately yields published_unverified for the publication predicate."],
      "grounding":[
        {
          "end_line":1227,
          "quote":"it has no\nclosed result and is never mapped to\n`indeterminate` or to any other core value",
          "section_id":"repo://stdo-v3-generation-rc9/claude/c2cfa9b908d1722ae3f26c32fa4ece691083bdc3/source/standards/WORLD_MODEL.md#WORLD_MODEL%2F14.%20Results%20of%20this%20profile",
          "start_line":1223
        }
      ],
      "key":"unrun_verification_and_standing",
      "statement":"An unrun direction verification has no acceptance result, including no indeterminate; the direction stays candidate. In conjunction it is a planned assessment without closed result if planned, otherwise uncovered obligation. A construction step needing it and stopping without it ends incomplete for candidate availability, not indeterminate, with unrun verification in work-state residuals. Stated absence/non-applicability are lawful admissibility values, not nonsatisfaction. Candidate-class/established are construct standings; candidate-class/formally closed are publication kinds, not results. A failed gate run does not falsify the construct.",
      "uncertainty":"The external construction-result mapping and conjunction machinery are referenced but not instantiated."
    }
